import{_ as i,o as e,c as l,a2 as s}from"./chunks/framework.BqNd1sPY.js";const u=JSON.parse('{"title":"内容编写规范","description":"","frontmatter":{},"headers":[],"relativePath":"07-来源与质量审计/内容编写规范.md","filePath":"07-来源与质量审计/内容编写规范.md"}'),t={name:"07-来源与质量审计/内容编写规范.md"};function r(o,a,n,d,c,p){return e(),l("div",null,[...a[0]||(a[0]=[s(`<h1 id="内容编写规范" tabindex="-1">内容编写规范 <a class="header-anchor" href="#内容编写规范" aria-label="Permalink to &quot;内容编写规范&quot;">​</a></h1><p>这套课程按 Wiki 方式维护。课程正文负责循序讲解，术语目录负责跨文章连接，二者不能各写一套互相漂移的定义。</p><h2 id="术语链接规则" tabindex="-1">术语链接规则 <a class="header-anchor" href="#术语链接规则" aria-label="Permalink to &quot;术语链接规则&quot;">​</a></h2><ol><li>核心术语统一登记在 <code>.vitepress/wiki-terms.mjs</code>。</li><li>每个术语必须同时在 <a href="./../05-速查表/术语速查">术语速查</a> 中拥有稳定的 <code>term-*</code> 锚点。</li><li>构建时会自动链接正文里的登记词和别名，并提供“定义 + 常见误解”的悬停预览。</li><li>标题、行内代码、代码块和已有链接不会被自动改写。</li><li>不在正文中粘贴 <code>localhost</code> 等环境相关的绝对地址；手工链接使用相对路径。</li></ol><p>新增术语时，必须在同一次修改中完成以下事项：</p><ul><li>写清标准名称、必要别名、一句话解释和常见误解。</li><li>给出稳定目标锚点，不能链接到笼统的目录首页。</li><li>检查别名不会误伤普通词或更长的专有名词。</li><li>在桌面端验证鼠标悬停，在键盘模式验证 Tab 聚焦，在手机端验证链接不造成横向溢出。</li></ul><p>普通动词、过于宽泛的词和只出现一次的临时缩写不应登记为术语。自动链接的目标是降低查找成本，不是让整页文字都变成链接。</p><h2 id="支持页面与图片" tabindex="-1">支持页面与图片 <a class="header-anchor" href="#支持页面与图片" aria-label="Permalink to &quot;支持页面与图片&quot;">​</a></h2><ul><li>支持入口统一指向 <code>/08-支持课程/</code>，课程页右侧保留悬浮入口。</li><li><code>public/support/alipay-reward.jpg</code> 是用户提供的原始打赏图片，只能原样展示，禁止裁剪、压缩、重绘、调色或替换。</li><li>任何修改支持页的内容都要保持语气克制：支持是自愿的，不影响学习内容的使用。</li></ul><h2 id="讲解规则" tabindex="-1">讲解规则 <a class="header-anchor" href="#讲解规则" aria-label="Permalink to &quot;讲解规则&quot;">​</a></h2><ul><li>先给直觉和具体数字，再给公式与术语。</li><li>首次引入概念时说明输入、动作、输出和适用边界。</li><li>把“事实”“工程经验”“近似估算”和“仍有争议的观点”明确区分。</li><li>不用单一 <a href="/LLMTrain/05-速查表/术语速查#term-loss" class="wiki-term" data-wiki-title="loss" data-wiki-summary="训练目标对应的误差标量，优化器尝试让它下降。" data-wiki-misconception="一个 loss 数值足以代表模型的全部质量。">loss</a>、排行榜分数或生成样例代替完整评测。</li><li>实战材料用于辅导学习；除非学习者明确要求，不替学习者直接完成训练结论。</li></ul><h2 id="提交前检查" tabindex="-1">提交前检查 <a class="header-anchor" href="#提交前检查" aria-label="Permalink to &quot;提交前检查&quot;">​</a></h2><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:check</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm docs:build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>内容审计会检查 Markdown 链接、公式围栏、Mermaid、课程天数，以及术语登记项与速查页锚点是否一致。</p>`,14)])])}const m=i(t,[["render",r]]);export{u as __pageData,m as default};
